-- Native time chain uses permanent foundation identity. All timestamps are local +08:00.
CREATE TABLE ty_shift_definition(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),code text NOT NULL,name text NOT NULL,color text NOT NULL CHECK(color ~ '^#[0-9A-Fa-f]{6}$'),description text NOT NULL DEFAULT '',updated_by bigint NOT NULL,UNIQUE(group_id,code)
);
CREATE TABLE ty_roster_period(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),
 period date NOT NULL CHECK(extract(day FROM period)=1),status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','closed')),
 label text NOT NULL,synthetic_version text,created_by bigint NOT NULL,closed_by bigint,closed_at timestamptz,
 UNIQUE(group_id,period),CHECK((status='closed')=(closed_at IS NOT NULL AND closed_by IS NOT NULL))
);
CREATE TABLE ty_roster_day(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,period_id bigint NOT NULL REFERENCES ty_roster_period(id),
 person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),
 home_company_id bigint NOT NULL REFERENCES ty_company(id),work_date date NOT NULL,
 day_kind text NOT NULL CHECK(day_kind IN('work','rest','annual_leave','sick_leave','personal_leave','holiday','absence')),
 calendar_note text NOT NULL DEFAULT '',UNIQUE(period_id,person_id,work_date)
);
CREATE TABLE ty_roster_segment(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,day_id bigint NOT NULL REFERENCES ty_roster_day(id),
 segment_no integer NOT NULL CHECK(segment_no>0),shift_code text NOT NULL,
 work_company_id bigint NOT NULL REFERENCES ty_company(id),department_id bigint NOT NULL REFERENCES ty_department(id),
 work_area_id bigint REFERENCES ty_work_area(id),start_at timestamp NOT NULL,end_at timestamp NOT NULL,
 overtime boolean NOT NULL DEFAULT false,leave_kind text CHECK(leave_kind IN('annual_leave','sick_leave','personal_leave','holiday','absence')),
 UNIQUE(day_id,segment_no),CHECK(end_at>start_at AND end_at<=start_at+interval '16 hours'),CHECK(NOT(overtime AND leave_kind IS NOT NULL))
);
CREATE INDEX ty_roster_segment_company ON ty_roster_segment(work_company_id,day_id);
CREATE TABLE ty_time_punch(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,segment_id bigint NOT NULL REFERENCES ty_roster_segment(id),
 direction text NOT NULL CHECK(direction IN('in','out')),punched_at timestamp NOT NULL,
 source text NOT NULL CHECK(source IN('synthetic','device','import')),source_ref text NOT NULL,
 UNIQUE(segment_id,direction)
);
CREATE TABLE ty_time_correction(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,segment_id bigint NOT NULL REFERENCES ty_roster_segment(id),
 direction text NOT NULL CHECK(direction IN('in','out')),corrected_at timestamp NOT NULL,
 reason text NOT NULL CHECK(length(btrim(reason))>=4),reviewed_by bigint NOT NULL,reviewed_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(segment_id,direction)
);
CREATE TABLE ty_roster_change(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,period_id bigint NOT NULL REFERENCES ty_roster_period(id),
 kind text NOT NULL CHECK(kind IN('shift_swap','secondment','cross_brand_support')),
 status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')),
 reason text NOT NULL CHECK(length(btrim(reason))>=4),patches jsonb NOT NULL CHECK(jsonb_typeof(patches)='array' AND jsonb_array_length(patches)>0),
 before_data jsonb,created_by bigint NOT NULL,decided_by bigint,decided_at timestamptz,decision_note text,
 CHECK((status='pending')=(decided_by IS NULL AND decided_at IS NULL))
);
CREATE FUNCTION fn_ty_time_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE d public.ty_roster_day%ROWTYPE; p public.ty_roster_period%ROWTYPE; s public.ty_roster_segment%ROWTYPE; e public.ty_employment%ROWTYPE; pid bigint; person bigint;
BEGIN
 IF TG_TABLE_NAME='ty_roster_day' THEN
  d:=NEW;SELECT * INTO p FROM public.ty_roster_period WHERE id=d.period_id FOR SHARE;
  SELECT * INTO e FROM public.ty_employment WHERE id=d.employment_id;
  IF e.person_id<>d.person_id OR e.company_id<>d.home_company_id OR e.group_id<>p.group_id OR e.status='cancelled' OR d.work_date<e.hire_date OR (e.leave_date IS NOT NULL AND d.work_date>e.leave_date) OR date_trunc('month',d.work_date)::date<>p.period THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='考勤日期、人员、雇佣和原雇主须一致'; END IF;
 ELSIF TG_TABLE_NAME='ty_roster_change' THEN
  SELECT * INTO p FROM public.ty_roster_period WHERE id=NEW.period_id FOR SHARE;
  IF TG_OP='UPDATE' AND OLD.status<>'pending' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已处理换班借调单不可改写'; END IF;
 ELSE
  IF TG_TABLE_NAME='ty_roster_segment' THEN s:=NEW; ELSE SELECT * INTO s FROM public.ty_roster_segment WHERE id=NEW.segment_id; END IF;
  SELECT * INTO d FROM public.ty_roster_day WHERE id=s.day_id;
  SELECT * INTO p FROM public.ty_roster_period WHERE id=d.period_id FOR SHARE;
  IF TG_TABLE_NAME='ty_roster_segment' THEN
   PERFORM pg_advisory_xact_lock(208208,d.person_id::integer);
   IF NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=s.work_company_id AND group_id=p.group_id) OR NOT EXISTS(SELECT 1 FROM public.ty_department WHERE id=s.department_id AND company_id=s.work_company_id) OR (s.work_area_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_work_area WHERE id=s.work_area_id AND company_id=s.work_company_id AND department_id=s.department_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='排班门店、部门和档口归属不一致'; END IF;
   IF NOT EXISTS(SELECT 1 FROM public.ty_shift_definition WHERE group_id=p.group_id AND code=s.shift_code) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='请先配置有效的班次定义'; END IF;
   IF s.start_at::date<>d.work_date OR s.end_at>d.work_date+interval '2 days' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='班段须从工作日开始，跨午夜不超过次日'; END IF;
   IF EXISTS(SELECT 1 FROM public.ty_roster_segment x JOIN public.ty_roster_day xd ON xd.id=x.day_id WHERE xd.person_id=d.person_id AND x.id<>s.id AND x.start_at<s.end_at AND s.start_at<x.end_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='同一人员跨门店的班段不能重叠'; END IF;
  ELSE
   IF TG_TABLE_NAME='ty_time_correction' AND TG_OP='UPDATE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='补卡核定记录不可改写'; END IF;
   IF TG_TABLE_NAME='ty_time_punch' THEN
    IF TG_OP='UPDATE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='原始打卡不可改写，请登记补卡'; END IF;
    IF NEW.punched_at<s.start_at-interval '4 hours' OR NEW.punched_at>s.end_at+interval '6 hours' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='打卡超出本班段关联窗口'; END IF;
   ELSE
    IF NEW.corrected_at<s.start_at-interval '4 hours' OR NEW.corrected_at>s.end_at+interval '6 hours' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='补卡超出本班段关联窗口'; END IF;
   END IF;
  END IF;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF TG_TABLE_NAME='ty_roster_day' THEN IF (NEW.period_id<>OLD.period_id OR NEW.person_id<>OLD.person_id OR NEW.employment_id<>OLD.employment_id OR NEW.work_date<>OLD.work_date OR NEW.home_company_id<>OLD.home_company_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='人日身份和归属日期不可改写'; END IF; END IF;
  IF TG_TABLE_NAME='ty_roster_segment' THEN IF NEW.day_id<>OLD.day_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='班段不能移动到其他人员日期'; END IF; END IF;
  IF TG_TABLE_NAME IN('ty_time_punch','ty_time_correction') THEN IF NEW.segment_id<>OLD.segment_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='打卡不能移动到其他班段'; END IF; END IF;
 END IF;
 IF p.status='closed' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='考勤月已封存，不能修改原始月记录'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER ty_roster_day_guard BEFORE INSERT OR UPDATE ON ty_roster_day FOR EACH ROW EXECUTE FUNCTION fn_ty_time_guard();
CREATE TRIGGER ty_roster_segment_guard BEFORE INSERT OR UPDATE ON ty_roster_segment FOR EACH ROW EXECUTE FUNCTION fn_ty_time_guard();
CREATE TRIGGER ty_time_punch_guard BEFORE INSERT OR UPDATE ON ty_time_punch FOR EACH ROW EXECUTE FUNCTION fn_ty_time_guard();
CREATE TRIGGER ty_time_correction_guard BEFORE INSERT OR UPDATE ON ty_time_correction FOR EACH ROW EXECUTE FUNCTION fn_ty_time_guard();
CREATE TRIGGER ty_roster_change_guard BEFORE INSERT OR UPDATE ON ty_roster_change FOR EACH ROW EXECUTE FUNCTION fn_ty_time_guard();
CREATE FUNCTION fn_ty_time_no_delete() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='考勤来源与审批轨迹保留，不允许直接删除'; END $$;
CREATE TRIGGER ty_roster_day_keep BEFORE DELETE ON ty_roster_day FOR EACH ROW EXECUTE FUNCTION fn_ty_time_no_delete();
CREATE TRIGGER ty_roster_segment_keep BEFORE DELETE ON ty_roster_segment FOR EACH ROW EXECUTE FUNCTION fn_ty_time_no_delete();
CREATE TRIGGER ty_time_punch_keep BEFORE DELETE ON ty_time_punch FOR EACH ROW EXECUTE FUNCTION fn_ty_time_no_delete();
CREATE TRIGGER ty_time_correction_keep BEFORE DELETE ON ty_time_correction FOR EACH ROW EXECUTE FUNCTION fn_ty_time_no_delete();
CREATE TRIGGER ty_roster_change_keep BEFORE DELETE ON ty_roster_change FOR EACH ROW EXECUTE FUNCTION fn_ty_time_no_delete();
CREATE FUNCTION fn_ty_roster_decide(p_id bigint,p_actor bigint,p_approve boolean,p_note text) RETURNS text LANGUAGE plpgsql SET search_path='' AS $$
DECLARE r public.ty_roster_change%ROWTYPE; x jsonb; s public.ty_roster_segment%ROWTYPE; oldrows jsonb:='[]';
BEGIN
 SELECT * INTO r FROM public.ty_roster_change WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR r.status<>'pending' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='换班借调单不存在或已处理'; END IF;
 IF length(btrim(coalesce(p_note,'')))<4 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='处理意见至少四字'; END IF;
 IF p_approve THEN
  FOR x IN SELECT value FROM jsonb_array_elements(r.patches) LOOP
   SELECT * INTO s FROM public.ty_roster_segment WHERE id=(x->>'segment_id')::bigint FOR UPDATE;
   IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.ty_roster_day WHERE id=s.day_id AND period_id=r.period_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='变更班段必须属于本考勤月'; END IF;
   IF EXISTS(SELECT 1 FROM public.ty_time_punch WHERE segment_id=s.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已发生打卡的班段不能换班，请走考勤修正'; END IF;
   oldrows:=oldrows||jsonb_build_array(to_jsonb(s));
   UPDATE public.ty_roster_segment SET start_at=coalesce((x->>'start_at')::timestamp,start_at),end_at=coalesce((x->>'end_at')::timestamp,end_at),work_company_id=coalesce((x->>'work_company_id')::bigint,work_company_id),department_id=coalesce((x->>'department_id')::bigint,department_id),work_area_id=CASE WHEN x?'work_area_id' THEN (x->>'work_area_id')::bigint ELSE work_area_id END,shift_code=coalesce(x->>'shift_code',shift_code) WHERE id=s.id;
  END LOOP;
 END IF;
 UPDATE public.ty_roster_change SET status=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,before_data=oldrows,decided_by=p_actor,decided_at=clock_timestamp(),decision_note=p_note WHERE id=r.id;
 RETURN CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END;
END $$;
CREATE VIEW v_ty_time_segment AS
SELECT s.*,d.period_id,d.person_id,d.employment_id,d.home_company_id,d.work_date,d.day_kind,
 coalesce(ci.corrected_at,pi.punched_at) actual_in,coalesce(co.corrected_at,po.punched_at) actual_out,
 (ci.id IS NOT NULL OR co.id IS NOT NULL) corrected,
 (extract(epoch FROM(s.end_at-s.start_at))/60)::integer planned_minutes,
 CASE WHEN s.leave_kind IS NOT NULL THEN 0 WHEN coalesce(ci.corrected_at,pi.punched_at) IS NULL OR coalesce(co.corrected_at,po.punched_at) IS NULL THEN 1 ELSE 0 END missing,
 CASE WHEN s.leave_kind IS NOT NULL THEN 0 ELSE greatest(0,extract(epoch FROM(coalesce(ci.corrected_at,pi.punched_at)-s.start_at))/60)::integer END late_minutes,
 CASE WHEN s.leave_kind IS NOT NULL THEN 0 ELSE greatest(0,extract(epoch FROM(s.end_at-coalesce(co.corrected_at,po.punched_at)))/60)::integer END early_minutes,
 CASE WHEN s.leave_kind IS NOT NULL OR coalesce(ci.corrected_at,pi.punched_at) IS NULL OR coalesce(co.corrected_at,po.punched_at) IS NULL THEN 0 ELSE greatest(0,extract(epoch FROM(coalesce(co.corrected_at,po.punched_at)-coalesce(ci.corrected_at,pi.punched_at)))/60)::integer END actual_minutes,
 CASE WHEN s.leave_kind IS NOT NULL OR coalesce(ci.corrected_at,pi.punched_at) IS NULL OR coalesce(co.corrected_at,po.punched_at) IS NULL THEN 0 ELSE greatest(0,extract(epoch FROM(least(s.end_at,coalesce(co.corrected_at,po.punched_at))-greatest(s.start_at,coalesce(ci.corrected_at,pi.punched_at))))/60)::integer END credited_minutes
FROM ty_roster_segment s JOIN ty_roster_day d ON d.id=s.day_id
LEFT JOIN ty_time_punch pi ON pi.segment_id=s.id AND pi.direction='in'
LEFT JOIN ty_time_punch po ON po.segment_id=s.id AND po.direction='out'
LEFT JOIN ty_time_correction ci ON ci.segment_id=s.id AND ci.direction='in'
LEFT JOIN ty_time_correction co ON co.segment_id=s.id AND co.direction='out';
CREATE VIEW v_ty_attendance_day AS
SELECT d.*,p.person_number,p.full_name,c.name home_company_name,l.region_code,l.currency_code,
 count(s.id)::integer segments,
 coalesce(sum(s.planned_minutes) FILTER(WHERE NOT s.overtime),0)::integer planned_minutes,
 coalesce(sum(s.actual_minutes),0)::integer actual_minutes,
 coalesce(sum(s.credited_minutes) FILTER(WHERE NOT s.overtime),0)::integer worked_minutes,
 coalesce(sum(s.credited_minutes) FILTER(WHERE s.overtime),0)::integer overtime_minutes,
 coalesce(sum(s.planned_minutes) FILTER(WHERE s.leave_kind IN('annual_leave','sick_leave','personal_leave','holiday')),0)::integer leave_minutes,
 coalesce(sum(s.planned_minutes) FILTER(WHERE s.leave_kind IN('annual_leave','sick_leave','holiday')),0)::integer paid_leave_minutes,
 coalesce(sum(s.planned_minutes) FILTER(WHERE s.leave_kind='personal_leave'),0)::integer unpaid_leave_minutes,
 coalesce(sum(s.late_minutes),0)::integer late_minutes,coalesce(sum(s.early_minutes),0)::integer early_minutes,
 coalesce(sum(s.missing),0)::integer missing_punches,count(s.id) FILTER(WHERE s.corrected)::integer corrected_segments,
 count(s.id) FILTER(WHERE s.work_company_id<>d.home_company_id)::integer support_segments,
 greatest(0,coalesce(sum(s.planned_minutes-s.credited_minutes) FILTER(WHERE NOT s.overtime AND (s.leave_kind IS NULL OR s.leave_kind='absence')),0))::integer unworked_minutes
FROM ty_roster_day d JOIN ty_person p ON p.id=d.person_id JOIN ty_company c ON c.id=d.home_company_id
CROSS JOIN LATERAL fn_ty_company_locale(c.id) l LEFT JOIN v_ty_time_segment s ON s.day_id=d.id
GROUP BY d.id,p.person_number,p.full_name,c.name,l.region_code,l.currency_code;
CREATE TABLE ty_time_payroll_link(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,period_id bigint NOT NULL REFERENCES ty_roster_period(id),
 batch_id bigint NOT NULL UNIQUE REFERENCES ty_payroll_batch(id),region_code text NOT NULL CHECK(region_code IN('CN','HK')),
 snapshot jsonb NOT NULL,created_by bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE FUNCTION fn_ty_time_link_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.ty_roster_period p JOIN public.ty_payroll_batch b ON b.group_id=p.group_id AND b.period=to_char(p.period,'YYYY-MM') WHERE p.id=NEW.period_id AND b.id=NEW.batch_id AND p.status='closed' AND b.status='confirmed' AND b.region_code=NEW.region_code) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='工资关联须对应同集团同月同地区的已封存考勤及已确认工资'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER ty_time_payroll_link_guard BEFORE INSERT ON ty_time_payroll_link FOR EACH ROW EXECUTE FUNCTION fn_ty_time_link_guard();
CREATE TRIGGER ty_time_payroll_link_keep BEFORE UPDATE OR DELETE ON ty_time_payroll_link FOR EACH ROW EXECUTE FUNCTION fn_ty_time_no_delete();
CREATE FUNCTION fn_ty_roster_period_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
BEGIN
 IF OLD.status='closed' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已封存考勤月不可改写'; END IF;
 IF NEW.group_id<>OLD.group_id OR NEW.period<>OLD.period THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='考勤月集团和月份不可修改'; END IF;
 IF NEW.status='closed' AND EXISTS(SELECT 1 FROM public.v_ty_time_segment WHERE period_id=NEW.id AND actual_out<=actual_in) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='实际下班必须晚于上班，不能封存'; END IF;
 IF NEW.status='closed' AND (EXISTS(SELECT 1 FROM public.v_ty_attendance_day WHERE period_id=NEW.id AND missing_punches>0) OR EXISTS(SELECT 1 FROM public.ty_roster_change WHERE period_id=NEW.id AND status='pending')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='缺卡或待批换班借调未处理，不能封存考勤月'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER ty_roster_period_guard BEFORE UPDATE ON ty_roster_period FOR EACH ROW EXECUTE FUNCTION fn_ty_roster_period_guard();
CREATE TRIGGER ty_roster_period_keep BEFORE DELETE ON ty_roster_period FOR EACH ROW EXECUTE FUNCTION fn_ty_time_no_delete();
INSERT INTO sys_check_registry(check_code,name,domain,kind,guard_object,guard_schema,guard_table,guard_kind,runner,assertion_sql) VALUES('TYHR.TIME-CHAIN','班段打卡报表与工资贯通','ATTENDANCE','ACL','ty_roster_segment_guard','public','ty_roster_segment','TRIGGER','node test/advanced-time.test.mjs','node test/advanced-time.test.mjs');
